export function parseDuration(text) {
  if (!text) throw new Error(`bad duration: ${text}`);
  let total = 0;
  let pos = 0;
  while (pos < text.length) {
    const match = /^(\\d+)(h|ms|m|s)/.exec(text.slice(pos));
    if (!match) throw new Error(`bad duration: ${text}`);
    total += Number(match[1]) * UNITS[match[2]];
    pos += match[0].length;
  }
  return total;
}
