src = """export function toRoman(n) {
  if (typeof n !== 'number' || !Number.isInteger(n) || n < 1 || n > 3999) {
    throw new RangeError('Input must be an integer between 1 and 3999');
  }

  const map = [
    [1000, 'M'], [900, 'CM'], [500, 'D'], [400, 'CD'],
    [100, 'C'], [90, 'XC'], [50, 'L'], [40, 'XL'],
    [10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I'],
  ];

  let result = '';
  for (const [value, numeral] of map) {
    while (n >= value) {
      result += numeral;
      n -= value;
    }
  }
  return result;
}

export function fromRoman(s) {
  if (typeof s !== 'string' || s.length === 0) {
    throw new Error('Invalid Roman numeral');
  }

  const values = {
    I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000,
  };

  // Check for invalid characters
  for (const ch of s) {
    if (!(ch in values)) {
      throw new Error('Invalid Roman numeral');
    }
  }

  let total = 0;
  let prev = 0;
  let repeatCount = 1;
  let prevChar = '';

  const nonRepeatable = new Set(['V', 'L', 'D']);

  for (let i = s.length - 1; i >= 0; i--) {
    const ch = s[i];
    const val = values[ch];

    if (ch === prevChar) {
      repeatCount++;
    } else {
      repeatCount = 1;
      prevChar = ch;
    }

    // Cannot repeat V, L, D
    if (repeatCount > 1 && nonRepeatable.has(ch)) {
      throw new Error('Invalid Roman numeral');
    }

    // Cannot repeat any numeral more than 3 times
    if (repeatCount > 3) {
      throw new Error('Invalid Roman numeral');
    }

    if (val < prev) {
      // Subtractive case
      // Only I, X, C can be subtractive
      if (ch !== 'I' && ch !== 'X' && ch !== 'C') {
        throw new Error('Invalid Roman numeral');
      }
      // Valid subtractive pairs: IV, IX, XL, XC, CD, CM
      const allowed = {
        I: new Set([5, 10]),       // V, X
        X: new Set([50, 100]),     // L, C
        C: new Set([500, 1000]),   // D, M
      };
      if (!allowed[ch].has(prev)) {
        throw new Error('Invalid Roman numeral');
      }
      total -= val;
    } else {
      total += val;
      prev = val;
    }
  }

  // Extra validation: re-convert and compare to catch invalid patterns
  // like IIV, IIX, VIV, etc.
  if (toRoman(total) !== s) {
    throw new Error('Invalid Roman numeral');
  }

  return total;
}
